// Social cards — four formats, shared DNA

function SocialBase({ w, h, children, style = {} }) {
  return (
    <div style={{
      width: w, height: h, background: '#1A3A5C', color: '#F2F6FB',
      position: 'relative', overflow: 'hidden', fontFamily: 'Inter, sans-serif',
      ...style,
    }}>
      {children}
    </div>
  );
}

// LinkedIn — 1200x627 landscape
function SocialLinkedIn({ guest }) {
  const deep = '#1A3A5C', alice = '#F2F6FB', gold = '#D4980F', sky = '#8AABC8';
  return (
    <SocialBase w={1200} h={627}>
      {/* motif behind */}
      <div style={{ position: 'absolute', inset: 0, opacity: 0.16 }}>
        <SignalMotif width={1200} height={627} color={alice} accent={gold} showPulse={false} lineCount={9} />
      </div>
      {/* gold hairline */}
      <div style={{ position: 'absolute', top: 0, left: 60, width: 80, height: 3, background: gold }} />
      {/* Header row */}
      <div style={{
        position: 'absolute', top: 40, left: 60, right: 60, zIndex: 2,
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
      }}>
        <SignalWordmarkInline color={alice} accent={gold} size={1.2} />
        <IssueNumber number={guest.episode} color={alice} accent={gold} size={1.1} />
      </div>
      {/* Layout grid */}
      <div style={{
        position: 'absolute', top: 120, left: 60, right: 60, bottom: 100, zIndex: 2,
        display: 'grid', gridTemplateColumns: '1fr 320px', gap: 48, alignItems: 'center',
      }}>
        {/* Quote + attribution */}
        <div>
          <div style={{
            fontFamily: 'Fraunces, serif', fontStyle: 'italic', fontWeight: 400,
            fontSize: 40, lineHeight: 1.2, letterSpacing: '-0.02em', color: alice,
            marginBottom: 28,
          }}>
            &ldquo;{guest.quote}&rdquo;
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <div style={{ width: 40, height: 1.5, background: gold }} />
            <div>
              <div style={{ fontSize: 16, fontWeight: 600, color: alice, letterSpacing: '-0.01em' }}>
                {guest.name}
              </div>
              <div style={{ fontSize: 13, color: alice, opacity: 0.7 }}>
                {guest.role} · {guest.agency}
              </div>
            </div>
          </div>
        </div>
        {/* Photo */}
        <div style={{
          position: 'relative', width: 320, height: 380, overflow: 'hidden',
          border: `1px solid rgba(242,246,251,0.2)`,
        }}>
          <img src={guest.photo} alt={guest.name}
               style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', filter: 'contrast(1.02) saturate(0.9)' }} />
          <div style={{
            position: 'absolute', top: 12, left: 12, width: 20, height: 20,
            borderTop: `1.5px solid ${gold}`, borderLeft: `1.5px solid ${gold}`,
          }} />
          <div style={{
            position: 'absolute', bottom: 12, right: 12, width: 20, height: 20,
            borderBottom: `1.5px solid ${gold}`, borderRight: `1.5px solid ${gold}`,
          }} />
        </div>
      </div>
      {/* Footer */}
      <div style={{
        position: 'absolute', bottom: 36, left: 60, right: 60, zIndex: 2,
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        fontSize: 12, letterSpacing: '0.22em', textTransform: 'uppercase',
        color: alice, opacity: 0.6, fontWeight: 500,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <img src="data:image/svg+xml;base64," alt="Mentis" style={{ height: 18 }} />
          <span>A Mentis Podcast</span>
        </div>
        <span style={{ fontFamily: 'Fraunces, serif', fontStyle: 'italic', textTransform: 'none', fontSize: 16, letterSpacing: '-0.01em', opacity: 0.85 }}>
          Listen now
        </span>
      </div>
    </SocialBase>
  );
}

// Instagram Square — 1080x1080
function SocialIGSquare({ guest }) {
  const deep = '#1A3A5C', alice = '#F2F6FB', gold = '#D4980F';
  return (
    <SocialBase w={1080} h={1080}>
      {/* full-bleed photo in top half */}
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 700, overflow: 'hidden' }}>
        <img src={guest.photo} alt={guest.name}
             style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', filter: 'contrast(1.02) saturate(0.9)' }} />
        {/* vignette to blend into deep */}
        <div style={{
          position: 'absolute', inset: 0,
          background: `linear-gradient(180deg, rgba(26,58,92,0.25) 0%, rgba(26,58,92,0.05) 40%, rgba(26,58,92,0.9) 95%)`,
        }} />
        {/* Corner marks */}
        <div style={{ position: 'absolute', top: 40, left: 40, width: 28, height: 28, borderTop: `2px solid ${gold}`, borderLeft: `2px solid ${gold}` }} />
        <div style={{ position: 'absolute', top: 40, right: 40, width: 28, height: 28, borderTop: `2px solid ${gold}`, borderRight: `2px solid ${gold}` }} />
        {/* episode number top right */}
        <div style={{ position: 'absolute', top: 48, right: 72, zIndex: 3 }}>
          <IssueNumber number={guest.episode} color={alice} accent={gold} size={1.3} />
        </div>
        {/* wordmark top left */}
        <div style={{ position: 'absolute', top: 48, left: 72, zIndex: 3 }}>
          <SignalWordmarkInline color={alice} accent={gold} size={1.4} />
        </div>
      </div>

      {/* lower — deep field with quote */}
      <div style={{
        position: 'absolute', top: 660, left: 0, right: 0, bottom: 0,
        padding: '60px 72px 56px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
        background: `linear-gradient(180deg, rgba(26,58,92,0) 0%, ${deep} 20%, ${deep} 100%)`,
      }}>
        {/* motif */}
        <div style={{ position: 'absolute', top: 40, left: 0, right: 0, opacity: 0.15 }}>
          <SignalMotif width={1080} height={140} color={alice} accent={gold} showPulse={false} lineCount={6} />
        </div>
        <div style={{ position: 'relative', zIndex: 2 }}>
          <div style={{ width: 60, height: 2, background: gold, marginBottom: 20 }} />
          <div style={{
            fontFamily: 'Fraunces, serif', fontStyle: 'italic', fontWeight: 400,
            fontSize: 38, lineHeight: 1.2, letterSpacing: '-0.02em', color: alice,
            marginBottom: 24, maxWidth: 900,
          }}>
            &ldquo;{guest.quote}&rdquo;
          </div>
          <div>
            <div style={{ fontSize: 20, fontWeight: 600, color: alice, letterSpacing: '-0.01em', marginBottom: 4 }}>
              {guest.name}
            </div>
            <div style={{ fontSize: 14, color: alice, opacity: 0.7 }}>
              {guest.role} · {guest.agency}
            </div>
          </div>
        </div>
        <div style={{ position: 'relative', zIndex: 2,
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
          borderTop: `1px solid rgba(242,246,251,0.18)`, paddingTop: 20,
          fontSize: 13, letterSpacing: '0.22em', textTransform: 'uppercase',
          color: alice, opacity: 0.6, fontWeight: 500,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <img src="data:image/svg+xml;base64," alt="Mentis" style={{ height: 20 }} />
            <span>A Mentis Podcast</span>
          </div>
          <span style={{ fontFamily: 'Fraunces, serif', fontStyle: 'italic', textTransform: 'none', fontSize: 18, letterSpacing: '-0.01em', opacity: 0.85 }}>
            Nothing is by accident.
          </span>
        </div>
      </div>
    </SocialBase>
  );
}

// Instagram Story — 1080x1920
function SocialIGStory({ guest }) {
  const deep = '#1A3A5C', alice = '#F2F6FB', gold = '#D4980F';
  return (
    <SocialBase w={1080} h={1920}>
      {/* Top — deep masthead */}
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 520, background: deep, overflow: 'hidden' }}>
        <div style={{ position: 'absolute', inset: 0, opacity: 0.2 }}>
          <SignalMotif width={1080} height={520} color={alice} accent={gold} showPulse={false} lineCount={9} />
        </div>
        <div style={{ position: 'absolute', top: 80, left: 80, zIndex: 2 }}>
          <IssueNumber number={guest.episode} color={alice} accent={gold} size={1.5} />
        </div>
        <div style={{ position: 'absolute', top: 160, left: 80, zIndex: 2 }}>
          <SignalWordmark size={1.9} color={alice} accent={gold} />
        </div>
      </div>

      {/* Middle — full photo */}
      <div style={{ position: 'absolute', top: 520, left: 0, right: 0, bottom: 640, overflow: 'hidden', background: deep }}>
        <img src={guest.photo} alt={guest.name}
             style={{ width: '100%', height: '100%', objectFit: 'contain', objectPosition: 'center top', filter: 'contrast(1.02) saturate(0.9)' }} />
        <div style={{
          position: 'absolute', inset: 0,
          background: `linear-gradient(180deg, rgba(26,58,92,0.3) 0%, rgba(26,58,92,0) 25%, rgba(26,58,92,0) 75%, rgba(26,58,92,0.95) 100%)`,
        }} />
        {/* frame marks */}
        <div style={{ position: 'absolute', top: 40, left: 40, width: 40, height: 40, borderTop: `2px solid ${gold}`, borderLeft: `2px solid ${gold}` }} />
        <div style={{ position: 'absolute', bottom: 40, right: 40, width: 40, height: 40, borderBottom: `2px solid ${gold}`, borderRight: `2px solid ${gold}` }} />
      </div>

      {/* Bottom — deep quote block */}
      <div style={{
        position: 'absolute', bottom: 0, left: 0, right: 0, height: 700, background: deep,
        padding: '80px 80px 100px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
      }}>
        <div>
          <div style={{ width: 60, height: 2, background: gold, marginBottom: 32 }} />
          <div style={{
            fontFamily: 'Fraunces, serif', fontStyle: 'italic', fontWeight: 400,
            fontSize: 58, lineHeight: 1.2, letterSpacing: '-0.02em', color: alice,
            marginBottom: 40,
          }}>
            &ldquo;{guest.quote}&rdquo;
          </div>
          <div style={{
            fontSize: 28, fontWeight: 600, color: alice, letterSpacing: '-0.01em', marginBottom: 6,
            fontFamily: 'Fraunces, serif',
          }}>
            {guest.name}
          </div>
          <div style={{ fontSize: 20, color: alice, opacity: 0.7 }}>
            {guest.role} · {guest.agency}
          </div>
        </div>
        <div style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
          borderTop: `1px solid rgba(242,246,251,0.2)`, paddingTop: 28,
          fontSize: 15, letterSpacing: '0.22em', textTransform: 'uppercase',
          color: alice, opacity: 0.7, fontWeight: 500,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
            <img src="data:image/svg+xml;base64," alt="Mentis" style={{ height: 24 }} />
            <span>Mentis Digital</span>
          </div>
          <span style={{ fontFamily: 'Fraunces, serif', fontStyle: 'italic', textTransform: 'none', fontSize: 22, letterSpacing: '-0.01em' }}>
            Swipe up →
          </span>
        </div>
      </div>
    </SocialBase>
  );
}

// 16:9 clip thumbnail — 1920x1080
function SocialClip16x9({ guest }) {
  const deep = '#1A3A5C', alice = '#F2F6FB', gold = '#D4980F';
  return (
    <SocialBase w={1920} h={1080}>
      {/* full-bleed photo left half */}
      <div style={{ position: 'absolute', top: 0, left: 0, width: 960, bottom: 0, overflow: 'hidden' }}>
        <img src={guest.photo} alt={guest.name}
             style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', filter: 'contrast(1.02) saturate(0.9)' }} />
        <div style={{
          position: 'absolute', inset: 0,
          background: `linear-gradient(90deg, rgba(26,58,92,0.1) 0%, rgba(26,58,92,0.3) 70%, ${deep} 100%)`,
        }} />
      </div>

      {/* right — deep with quote */}
      <div style={{
        position: 'absolute', top: 0, right: 0, width: 960, bottom: 0,
        padding: '80px 80px 80px 40px',
        display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
      }}>
        <div style={{ position: 'absolute', inset: 0, opacity: 0.12 }}>
          <SignalMotif width={960} height={1080} color={alice} accent={gold} showPulse={false} lineCount={9} />
        </div>

        {/* top — episode + wordmark */}
        <div style={{ position: 'relative', zIndex: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <SignalWordmarkInline color={alice} accent={gold} size={1.3} />
          <IssueNumber number={guest.episode} color={alice} accent={gold} size={1.2} />
        </div>

        {/* centre — pull quote */}
        <div style={{ position: 'relative', zIndex: 2 }}>
          <div style={{ width: 60, height: 2, background: gold, marginBottom: 28 }} />
          <div style={{
            fontFamily: 'Fraunces, serif', fontStyle: 'italic', fontWeight: 400,
            fontSize: 52, lineHeight: 1.18, letterSpacing: '-0.02em', color: alice,
            marginBottom: 32,
          }}>
            &ldquo;{guest.quote}&rdquo;
          </div>
          <div style={{ fontSize: 22, fontWeight: 600, color: alice, fontFamily: 'Fraunces, serif', marginBottom: 4 }}>
            {guest.name}
          </div>
          <div style={{ fontSize: 16, color: alice, opacity: 0.7 }}>
            {guest.role} · {guest.agency}
          </div>
        </div>

        {/* bottom — mentis + tagline */}
        <div style={{
          position: 'relative', zIndex: 2,
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
          borderTop: `1px solid rgba(242,246,251,0.18)`, paddingTop: 24,
          fontSize: 12, letterSpacing: '0.22em', textTransform: 'uppercase',
          color: alice, opacity: 0.65, fontWeight: 500,
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <img src="data:image/svg+xml;base64," alt="Mentis" style={{ height: 20 }} />
            <span>A Mentis Podcast</span>
          </div>
          <span style={{ fontFamily: 'Fraunces, serif', fontStyle: 'italic', textTransform: 'none', fontSize: 16, letterSpacing: '-0.01em', opacity: 0.9 }}>
            Nothing is by accident.
          </span>
        </div>
      </div>
    </SocialBase>
  );
}

Object.assign(window, { SocialLinkedIn, SocialIGSquare, SocialIGStory, SocialClip16x9 });
